SELECT 
    ,
    d.dept_name
FROM employee e
LEFT JOIN department d ON e.dept_id = d.id

    e.status = 1

        AND e.emp_name LIKE CONCAT('%', #{empName}, '%')


        AND e.emp_no = #{empNo}



        AND e.dept_id = #{deptId}


        AND e.gender = #{gender}


        AND e.job_title = #{jobTitle}


        AND e.status = #{status}


ORDER BY e.id

